def estado_liberada_y_controles_cerrados(apps, schema_editor):
    """
    Crea el estado «Liberada por calidad» de la orden de trabajo y marca como
    aprobados los controles de las ordenes que ya se cerraron con la regla
    anterior, para que el historial quede coherente.
    """
    EstadoDocumento = apps.get_model("comercial", "EstadoDocumento")
    ControlCalidad = apps.get_model("calidad", "ControlCalidad")
    EstadoDocumento.objects.get_or_create(
        tipo_documento="orden_trabajo", codigo="liberada",
        defaults={"nombre": "Liberada por calidad", "es_final": False},
    )
    ControlCalidad.objects.filter(
        orden_trabajo__estado__codigo="cerrada"
    ).exclude(estado="aprobado").update(estado="aprobado")



